-- =============================================================
-- Deleted-user archive (dua), part 5: table registry for the Records tab.
-- Generated 2026-10-07 from the research inventory (final_tables.json, 174 tables
-- in the deletion closure): a human label, a category and the columns to show.
-- A table the registry does not know yet shows under "Other" with all columns;
-- dua.registry_gaps() lists tables in the live closure missing from here.
-- =============================================================
CREATE TABLE IF NOT EXISTS dua.table_registry (
  table_name text PRIMARY KEY,
  label text NOT NULL,
  category text NOT NULL,
  display_columns text[] NOT NULL DEFAULT '{}',
  notes text
);
ALTER TABLE dua.table_registry ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dua.table_registry FROM PUBLIC, anon, authenticated;

ON CONFLICT (table_name) DO UPDATE SET label = EXCLUDED.label, category = EXCLUDED.category,
  display_columns = EXCLUDED.display_columns, notes = EXCLUDED.notes;

-- Tables a delete can reach today that the registry does not describe. Should be empty.
CREATE OR REPLACE FUNCTION dua.registry_gaps() RETURNS TABLE (table_name text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  WITH RECURSIVE closure(rel) AS (
    SELECT 'auth.users'::regclass::oid
    UNION
    SELECT c.conrelid FROM pg_catalog.pg_constraint c JOIN closure cl ON c.confrelid = cl.rel
    WHERE c.contype = 'f' AND c.confdeltype = 'c'
  )
  SELECT rel::regclass::text FROM closure
  WHERE rel::regclass::text NOT IN (SELECT r.table_name FROM dua.table_registry r)
  ORDER BY 1
$$;
REVOKE EXECUTE ON FUNCTION dua.registry_gaps() FROM PUBLIC, anon, authenticated;
