INSERT INTO dua.table_registry (table_name, label, category, display_columns, notes) VALUES
  ('auth.users', 'Login account', 'Account and devices', ARRAY['email', 'phone', 'created_at', 'last_sign_in_at', 'email_confirmed_at', 'banned_until'], 'Root of the cascade. Keep raw_app_meta_data / raw_user_meta_data (provider, names), no secrets in them on prod (2 rows carry ids in raw_user_meta_data). ~3405 rows overall.'),
  ('auth.identities', 'Sign-in methods', 'Account and devices', ARRAY['provider', 'email', 'last_sign_in_at', 'created_at'], 'One row per login provider; provider_id equals the user id for email logins. identity_data holds email/sub claims (PII, not a secret). ~3080 rows overall.'),
  ('auth.mfa_factors', 'Two-factor devices', 'Account and devices', ARRAY['factor_type', 'status', 'friendly_name', 'created_at'], '0 rows on prod.'),
  ('auth.mfa_recovery_code_sets', 'Two-factor recovery code sets', 'Account and devices', ARRAY['created_at', 'failed_verification_count'], '0 rows on prod.'),
  ('auth.oauth_authorizations', 'OAuth app authorizations', 'Account and devices', ARRAY['status', 'scope', 'created_at', 'approved_at'], '0 rows on prod. user_id FK has no index.'),
  ('auth.oauth_consents', 'OAuth app consents', 'Account and devices', ARRAY['scopes', 'granted_at', 'revoked_at'], '0 rows on prod.'),
