  ('public.ai_usage_logs', 'AI request log', 'Account and devices', ARRAY['created_at', 'service_type', 'questions_generated', 'tokens_used', 'request_status', 'error_message'], 'FK goes straight to auth.users. request_metadata may hold prompt details.'),
  ('public.profiles', 'Profile', 'Account and devices', ARRAY['full_name', 'email', 'phone', 'admission_number', 'roll_number', 'is_active'], 'Header data. avatar_path points into the user-avatars bucket (file is not deleted). ~3372 rows overall.'),
