  ('auth.refresh_tokens', 'Refresh tokens', 'Account and devices', ARRAY['created_at', 'updated_at', 'revoked'], 'user_id here is varchar, not an FK; rows go via session_id CASCADE (0 tokens without a session on prod). ~17769 rows overall.'),
  ('public.appointments', 'Teacher appointments', 'PTM', ARRAY['appointment_date', 'start_time', 'end_time', 'purpose', 'status', 'teacher_notes'], 'CASCADE on both student_id and teacher_id; neither FK is indexed.'),
